text = text.replace('<div class="pane-container tab-pane" id="pane-jobs-input" data-tab-id="jobs-input" data-tab-url="/admin/runs/{{ run.run_id }}/tabs/jobs-input">', '<div class="pane-container tab-pane" id="pane-jobs-input" role="tabpanel" aria-labelledby="tab-btn-jobs-input" data-tab-id="jobs-input" data-tab-url="/admin/runs/{{ run.run_id }}/tabs/jobs-input">')
