text = text.replace("  document.querySelectorAll('.tab-pane').forEach(p => {\n    p.style.display = 'none';\n    p.classList.remove('active');\n  });\n  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));\n  const pane = document.getElementById('pane-' + id);\n  pane.style.display = 'block';\n  pane.classList.add('active');\n  document.getElementById('tab-btn-' + id).classList.add('active');", "  document.querySelectorAll('.tab-pane').forEach(p => {\n    p.style.display = 'none';\n    p.classList.remove('active');\n    p.hidden = true;\n  });\n  document.querySelectorAll('.tab-btn').forEach(b => {\n    b.classList.remove('active');\n    b.setAttribute('aria-selected', 'false');\n  });\n  const pane = document.getElementById('pane-' + id);\n  pane.style.display = 'block';\n  pane.classList.add('active');\n  pane.hidden = false;\n  const button = document.getElementById('tab-btn-' + id);\n  button.classList.add('active');\n  button.setAttribute('aria-selected', 'true');")
p.write_text(text, encoding='utf-8')
print('patched run_detail tabs')
